SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.complete_cast cc, public.comp_cast_type cct1, public.comp_cast_type cct2, public.company_name cn, public.company_type ct, public.info_type it1, public.info_type it2, public.keyword k, public.kind_type kt, public.movie_companies mc, public.movie_info mi, public.movie_info_idx mi_idx, public.movie_keyword mk WHERE kt.id = title.kind_id AND title.id = mi.movie_id AND title.id = mk.movie_id AND title.id = mi_idx.movie_id AND title.id = mc.movie_id AND title.id = cc.movie_id AND k.id = mk.keyword_id AND it1.id = mi.info_type_id AND it2.id = mi_idx.info_type_id AND ct.id = mc.company_type_id AND cn.id = mc.company_id AND cct1.id = cc.subject_id AND cct2.id = cc.status_id AND cct1.kind = 'cast' AND cct2.kind = 'complete' AND cn.country_code != '[us]' AND it1.info = 'countries' AND it2.info = 'rating' AND (k.keyword = 'murder' OR k.keyword = 'murder-in-title' OR k.keyword = 'blood' OR k.keyword = 'violence') AND (kt.kind = 'movie' OR kt.kind = 'episode') AND (mi.info = 'Sweden' OR mi.info = 'Norway' OR mi.info = 'Germany' OR mi.info = 'Denmark' OR mi.info = 'Swedish' OR mi.info = 'Danish' OR mi.info = 'Norwegian' OR mi.info = 'German' OR mi.info = 'USA' OR mi.info = 'American') AND title.production_year > 2005);
